           })
         );
         const impactedCount = assets.filter(
           (asset) => incident?.assetId === asset.id || litNodes.has(asset.id)
         ).length;

         return (
           <section
             key={zoneName}
-            className="relative min-h-[92px] overflow-hidden rounded-[22px] border"
