+// ── Types ─────────────────────────────────────────────────────────────────
+
+type PipelineStep = "sentinel" | "triton" | "hermes";
+type ResultType = "asset-list" | "cascade" | "technician" | "forecast" | "generic";
+
+interface PipelineState {
