}

function getDerivedStatus(
  asset: Asset,
  incident: Incident | undefined,
  litNodes: Set<string>

export type ZoneVariant =
  | "a"
  | "b"
  | "mechanical"
  | "electrical"
  | "power"
  | "cooling"
  | "compute"
